#!/usr/bin/env python3
import os
import sys

BASE = os.path.dirname(os.path.abspath(__file__))
SRC_INPUT = os.path.join(BASE, "src", "INPUT.DAT")
DATA_DIR = os.path.join(BASE, "data")
ACCOUNTS_PATH = os.path.join(DATA_DIR, "ACCOUNTS.DAT")
BOOKS_PATH = os.path.join(DATA_DIR, "BOOKS.DAT")
TRANSACTIONS_PATH = os.path.join(DATA_DIR, "TRANSACTIONS.DAT")

ACCOUNT_LEN = 34
BOOK_LEN = 28
TRANSACTION_LEN = 22
INPUT_LEN = 22
MODULUS = 10_000_000_000


def digit_of(byte):
    if 48 <= byte <= 57:
        return byte - 48
    if byte == 0 or byte == 32:
        return 0
    if 65 <= byte <= 90 or 97 <= byte <= 122:
        return (byte - 48) % 10
    if byte > 127:
        return 0
    return (byte - 48) % 10


def numeric_value(field):
    value = 0
    for byte in field:
        value = value * 10 + digit_of(byte)
    return value


def amount_field_bytes(field):
    return bytes(48 if (byte == 0 or byte == 32) else byte for byte in field)


def store_balance(value):
    if value < 0:
        value = -value
    return value % MODULUS


def read_file(path):
    with open(path, "rb") as handle:
        return bytearray(handle.read())


def write_file(path, data):
    with open(path, "wb") as handle:
        handle.write(data)


def records(data, record_len):
    buffer = bytearray(record_len)
    offset = 0
    while offset < len(data):
        chunk = data[offset:offset + record_len]
        buffer[0:len(chunk)] = chunk
        yield offset, buffer, len(chunk) < record_len
        offset += record_len


def load_input():
    data = read_file(SRC_INPUT)
    if not data:
        return None
    buffer = bytearray(INPUT_LEN)
    chunk = data[:INPUT_LEN]
    buffer[0:len(chunk)] = chunk
    return bytes(buffer)


def valid_transaction(record, buyer, seller, book):
    buyer_found = False
    seller_found = False
    book_found = False
    valid_owner = False

    for _, account, _ in records(read_file(ACCOUNTS_PATH), ACCOUNT_LEN):
        account_id = bytes(account[0:4])
        if account_id == buyer:
            buyer_found = True
        if account_id == seller:
            seller_found = True

    for _, book_record, _ in records(read_file(BOOKS_PATH), BOOK_LEN):
        book_id = bytes(book_record[0:4])
        if book_id == book:
            book_found = True
            if bytes(book_record[24:28]) == seller:
                valid_owner = True

    return buyer_found and seller_found and book_found and valid_owner


def apply_transaction(buyer, seller, book, amount_value, trans_amount):
    account_data = read_file(ACCOUNTS_PATH)
    aborted = False

    for offset, account, short in records(account_data, ACCOUNT_LEN):
        account_id = bytes(account[0:4])
        if account_id == buyer:
            if short:
                aborted = True
                break
            balance = numeric_value(account[24:34])
            account[24:34] = f"{store_balance(balance - amount_value):010d}".encode("ascii")
            account_data[offset:offset + ACCOUNT_LEN] = account
            if account_id == seller:
                aborted = True
                break
        elif account_id == seller:
            if short:
                aborted = True
                break
            balance = numeric_value(account[24:34])
            account[24:34] = f"{store_balance(balance + amount_value):010d}".encode("ascii")
            account_data[offset:offset + ACCOUNT_LEN] = account

    write_file(ACCOUNTS_PATH, account_data)
    if aborted:
        return False

    book_data = read_file(BOOKS_PATH)
    for offset, book_record, short in records(book_data, BOOK_LEN):
        if bytes(book_record[0:4]) == book:
            if short:
                aborted = True
                break
            book_record[24:28] = buyer
            book_data[offset:offset + BOOK_LEN] = book_record

    write_file(BOOKS_PATH, book_data)
    if aborted:
        return False

    if not os.path.exists(TRANSACTIONS_PATH):
        return False

    transaction = book + trans_amount + seller + buyer
    with open(TRANSACTIONS_PATH, "ab") as handle:
        handle.write(transaction)

    return True


def main():
    record = load_input()
    if record is None:
        print("Error: Input file is empty")
        return 0

    buyer = record[0:4]
    seller = record[4:8]
    book = record[8:12]
    raw_amount = record[12:22]
    amount_12 = amount_field_bytes(raw_amount) + b"00"
    amount_value = numeric_value(amount_12)

    valid = valid_transaction(record, buyer, seller, book)
    print(" ")

    if not valid:
        print("Transaction failed due to validation errors")
        return 0

    completed = apply_transaction(buyer, seller, book, amount_value, amount_field_bytes(raw_amount))
    if not completed:
        return 1

    print("Transaction completed successfully")
    return 0


if __name__ == "__main__":
    sys.exit(main())
PYEOF
